import{_ as o,o as t,c as a,a4 as i}from"./chunks/framework.vNSRaLQv.js";const _=JSON.parse('{"title":"联想小新 Fn+Q 野兽模式无法开启 - 解决方案","description":"","frontmatter":{"title":"联想小新 Fn+Q 野兽模式无法开启 - 解决方案","date":"2026-07-04T00:00:00.000Z"},"headers":[],"relativePath":"posts/Fn+Q野兽模式修复方法.md","filePath":"posts/Fn+Q野兽模式修复方法.md"}'),l={name:"posts/Fn+Q野兽模式修复方法.md"};function d(n,e,r,c,h,s){return t(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="联想小新-fn-q-野兽模式无法开启-解决方案" tabindex="-1">联想小新 Fn+Q 野兽模式无法开启 - 解决方案 <a class="header-anchor" href="#联想小新-fn-q-野兽模式无法开启-解决方案" aria-label="Permalink to &quot;联想小新 Fn+Q 野兽模式无法开启 - 解决方案&quot;">​</a></h1><h2 id="问题现象" tabindex="-1">问题现象 <a class="header-anchor" href="#问题现象" aria-label="Permalink to &quot;问题现象&quot;">​</a></h2><p>按 Fn+Q 组合键无反应，无法切换野兽模式。</p><h2 id="根本原因" tabindex="-1">根本原因 <a class="header-anchor" href="#根本原因" aria-label="Permalink to &quot;根本原因&quot;">​</a></h2><p>Lenovo Notebook ITS Service 服务未运行或未设置为自动启动。</p><h2 id="成功解决方案" tabindex="-1">成功解决方案 <a class="header-anchor" href="#成功解决方案" aria-label="Permalink to &quot;成功解决方案&quot;">​</a></h2><h3 id="第一步-启用-its-服务" tabindex="-1">第一步：启用 ITS 服务 <a class="header-anchor" href="#第一步-启用-its-服务" aria-label="Permalink to &quot;第一步：启用 ITS 服务&quot;">​</a></h3><ol><li>按 <code>Win+R</code>，输入 <code>services.msc</code>，回车</li><li>找到 <code>Lenovo Notebook ITS Service</code></li><li>右键 → 属性</li><li>启动类型改为 <code>自动</code></li><li>点击 <code>启动</code> 按钮</li><li>点击 <code>确定</code></li></ol><h3 id="第二步-验证" tabindex="-1">第二步：验证 <a class="header-anchor" href="#第二步-验证" aria-label="Permalink to &quot;第二步：验证&quot;">​</a></h3><ul><li>按 Fn+Q，屏幕应显示模式切换图标</li><li>野兽模式：开机键亮红灯</li><li>安静模式：开机键亮蓝灯</li><li>均衡模式：开机键亮白灯</li></ul><h2 id="不需要的操作" tabindex="-1">不需要的操作 <a class="header-anchor" href="#不需要的操作" aria-label="Permalink to &quot;不需要的操作&quot;">​</a></h2><table tabindex="0"><thead><tr><th>操作</th><th>是否必要</th><th>说明</th></tr></thead><tbody><tr><td>安装 Lenovo Hotkeys</td><td>不必要</td><td>核心功能不依赖此软件</td></tr><tr><td>禁用 LenovoHotkeyService</td><td>可选</td><td>与ITS服务独立</td></tr><tr><td>禁用 LenovoFnAndFunctionKeys</td><td>不要禁用</td><td>Fn+Q核心服务</td></tr></tbody></table><h2 id="保留的关键服务" tabindex="-1">保留的关键服务 <a class="header-anchor" href="#保留的关键服务" aria-label="Permalink to &quot;保留的关键服务&quot;">​</a></h2><ul><li><code>LenovoFnAndFunctionKeys</code> - Fn+Q功能核心服务</li><li><code>LITSSVC</code> (Lenovo Notebook ITS Service) - 本问题的关键修复点</li></ul><h2 id="卸载-lenovo-hotkeys-可选" tabindex="-1">卸载 Lenovo Hotkeys（可选） <a class="header-anchor" href="#卸载-lenovo-hotkeys-可选" aria-label="Permalink to &quot;卸载 Lenovo Hotkeys（可选）&quot;">​</a></h2><ol><li>设置 → 应用 → 已安装的应用</li><li>搜索&quot;Lenovo Hotkeys&quot;，卸载</li><li>服务中禁用 <code>LenovoHotkeyService</code></li></ol><hr><p>记录时间：2026年7月4日</p>',18)])])}const b=o(l,[["render",d]]);export{_ as __pageData,b as default};
